import c2025 from '@/lib/tax/config/2025.json';
import c2026 from '@/lib/tax/config/2026.json';

/**
 * Year/province configuration. The JSON files are generated by `scripts/generate-config.py`;
 * edit that script (not the JSON) when updating parameters.
 */

export const SUPPORTED_YEARS = [2025, 2026] as const;
export type TaxYear = (typeof SUPPORTED_YEARS)[number];
export const DEFAULT_YEAR: TaxYear = 2025;

export const PROVINCES = [
  { code: 'AB', name: 'Alberta' },
  { code: 'BC', name: 'British Columbia' },
  { code: 'MB', name: 'Manitoba' },
  { code: 'NB', name: 'New Brunswick' },
  { code: 'NL', name: 'Newfoundland and Labrador' },
  { code: 'NS', name: 'Nova Scotia' },
  { code: 'NT', name: 'Northwest Territories' },
  { code: 'NU', name: 'Nunavut' },
  { code: 'ON', name: 'Ontario' },
  { code: 'PE', name: 'Prince Edward Island' },
  { code: 'QC', name: 'Quebec' },
  { code: 'SK', name: 'Saskatchewan' },
  { code: 'YT', name: 'Yukon' },
] as const;
export type ProvinceCode = (typeof PROVINCES)[number]['code'];
export const PROVINCE_CODES = PROVINCES.map((p) => p.code) as unknown as [ProvinceCode, ...ProvinceCode[]];

export type Bracket = { upTo: number | null; rate: number };

export type BpaConfig =
  | { base: number; min?: number; phaseoutStart?: number; phaseoutEnd?: number }
  | { followsFederal: true };

export type TaxReductionConfig =
  | { type: 'ontario'; basic: number; perDependant: number }
  | {
      type: 'linear';
      basic: number;
      spouse?: number;
      perChild?: number;
      threshold: number;
      rate: number;
      incomeBasis: 'individual' | 'family';
    };

/** Benefit parameters vary by program; each program's calculator documents its own shape. */
export type BenefitConfig = { id: string; name: string; onReturn?: boolean; [key: string]: any };

export type QuebecConfig = {
  livingAloneAmount: number;
  workerDeductionRate: number;
  workerDeductionMax: number;
  workPremium: {
    singleRate: number;
    coupleRate: number;
    singleParentRate: number;
    coupleWithChildrenRate: number;
    singleExclusion: number;
    coupleExclusion: number;
    singleThreshold: number;
    coupleThreshold: number;
    reductionRate: number;
  };
  solidarity: {
    qstBasic: number;
    qstSpouse: number;
    qstLivingAlone: number;
    housingCouple: number;
    housingSingle: number;
    housingPerChild: number;
    threshold: number;
    rate: number;
  };
  familyAllowance: {
    twoParentMax: number;
    twoParentMin: number;
    singleParentMax: number;
    singleParentMin: number;
    coupleThreshold: number;
    singleParentThreshold: number;
    rate: number;
  };
};

export type ProvinceConfig = {
  name: string;
  brackets: Bracket[];
  lowestRate: number;
  basicPersonalAmount: BpaConfig;
  spouseAmount: { max: number; threshold: number; followsFederal?: boolean };
  disabilityAmount: number;
  canadaEmploymentAmount?: number;
  donationCredit: { first200Rate: number; over200Rate: number; topRate?: number; topRateIncomeThreshold?: number };
  dividendTaxCreditRate: number;
  surtax?: { threshold: number; rate: number }[];
  healthPremium?: { from: number; rate: number; base: number; max: number }[];
  taxReduction?: TaxReductionConfig;
  benefits: BenefitConfig[];
  notes: string[];
  quebec?: QuebecConfig;
};

export type TaxYearConfig = {
  year: number;
  federal: {
    brackets: Bracket[];
    lowestRate: number;
    basicPersonalAmount: { base: number; min: number; phaseoutStart: number; phaseoutEnd: number };
    canadaEmploymentAmountMax: number;
    disabilityAmount: number;
    donationCredit: { first200Rate: number; over200Rate: number; over200TopRate: number; topRateIncomeThreshold: number };
    dividendTaxCredit: { eligibleGrossUp: number; eligibleRate: number };
    quebecAbatement: number;
  };
  payroll: {
    cpp: { ympe: number; yampe: number; basicExemption: number; baseRate: number; firstEnhancedRate: number; cpp2Rate: number };
    qpp: { baseRate: number; firstEnhancedRate: number; qpp2Rate: number };
    ei: { maxInsurableEarnings: number; rate: number; quebecRate: number };
    qpip: { maxInsurableEarnings: number; rate: number };
  };
  benefits: {
    cwb: {
      singleMax: number;
      familyMax: number;
      singlePhaseoutStart: number;
      singlePhaseoutEnd: number;
      familyPhaseoutStart: number;
      familyPhaseoutEnd: number;
      disabilityMax: number;
      disabilitySingleStart: number;
      disabilitySingleEnd: number;
      disabilityFamilyStart: number;
      disabilityFamilyEndOne: number;
      disabilityFamilyEndBoth: number;
      workingIncomeBase: number;
      phaseInRate: number;
      phaseOutRate: number;
      disabilityWorkingIncomeBase: number;
      disabilityPhaseInRate: number;
      minimumAge: number;
    };
    gstHst: {
      baseAdult: number;
      baseSpouse: number;
      baseSingleParentFirstChild: number;
      perChild: number;
      singleAdditionalBase: number;
      singleAdditionalMax: number;
      singleAdditionalRate: number;
      enhancementFactor: number;
      reductionBase: number;
      reductionRate: number;
    };
    ccb: {
      under6: number;
      age6to17: number;
      threshold1: number;
      threshold2: number;
      rates1: number[];
      rates2: number[];
    };
  };
  deductions: {
    childCareCaps: { under7: number; age7to16: number; dtcEligible: number };
    childCareEarnedIncomeFraction: number;
  };
  provinces: Record<ProvinceCode, ProvinceConfig>;
};

const CONFIGS: Record<TaxYear, TaxYearConfig> = {
  2025: c2025 as unknown as TaxYearConfig,
  2026: c2026 as unknown as TaxYearConfig,
};

export function getConfig(year: number = DEFAULT_YEAR): TaxYearConfig {
  const cfg = CONFIGS[year as TaxYear];
  if (!cfg) throw new Error(`Unsupported tax year ${year}. Supported: ${SUPPORTED_YEARS.join(', ')}`);
  return cfg;
}

export function getProvince(cfg: TaxYearConfig, code: ProvinceCode): ProvinceConfig {
  const p = cfg.provinces[code];
  if (!p) throw new Error(`Unsupported province ${code}`);
  return p;
}

export function provinceName(code: ProvinceCode): string {
  return PROVINCES.find((p) => p.code === code)?.name ?? code;
}
